import{Z as t,e as a,f as s,a0 as i}from"./chunks/framework.DmpHOl9T.js";const h=JSON.parse('{"title":"Custom Field","description":"","frontmatter":{},"headers":[],"relativePath":"fields/custom-field.md","filePath":"fields/custom-field.md","lastUpdated":1782532814000}'),o={name:"fields/custom-field.md"};function r(d,e,l,n,p,u){return a(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="custom-field" tabindex="-1">Custom Field <a class="header-anchor" href="#custom-field" aria-label="Permalink to &quot;Custom Field&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>For plugin developers building a new adapter, see <a href="/guides/fields/bringing-your-craft-field-into-formie-custom-field-adapters">Bringing your Craft field into Formie (Custom Field adapters)</a>.</p></div><p>The Custom Field field lets a form use supported Craft fields through Formie without adding a separate Formie field type for every provider.</p><p>Custom Field is adapter-based. Each available option in <strong>Custom Field Type</strong> has explicit Formie support for rendering, validation, submissions, email summaries, exports, integrations and GraphQL.</p><h2 id="supported-adapters" tabindex="-1">Supported Adapters <a class="header-anchor" href="#supported-adapters" aria-label="Permalink to &quot;Supported Adapters&quot;">​</a></h2><p>Formie includes these adapters:</p><ul><li><strong>Link</strong> for URL, email, phone and SMS link values from Craft’s Link field.</li><li><strong>Address (Google Maps)</strong> for supported Google Maps Craft field classes, when the plugin is installed.</li><li><strong>Maps</strong> for supported Maps/SimpleMap Craft field classes, when the plugin is installed.</li></ul><p>Only available adapters are shown in the field settings. Third-party developers can register additional adapters for their own Craft fields.</p><h2 id="field-settings" tabindex="-1">Field Settings <a class="header-anchor" href="#field-settings" aria-label="Permalink to &quot;Field Settings&quot;">​</a></h2><ol><li>Add <strong>Custom Field</strong> to a form.</li><li>Choose a <strong>Custom Field Type</strong> in the picker modal.</li><li>Configure the field in the regular field settings modal.</li></ol><p>The Custom Field Type is chosen once when the field is created. It cannot be changed later because each adapter can store a different value shape. To use a different adapter, add a new Custom Field.</p><p>The settings change depending on the selected adapter. For example, Link fields expose allowed link types, URL options, label and advanced-attribute settings, while map adapters expose address and coordinate defaults, map visibility, latitude/longitude display, current-location behaviour and zoom options where supported.</p><p>The Link adapter supports the text-based Craft Link types that can be rendered on public forms without Craft control-panel element selectors: URL, Email, Phone and SMS. Entry, Asset and Category link types are not included in the front-end adapter.</p><p>When a Link field allows one link type, Formie renders a single value input and stores the type in a hidden input. When multiple link types are enabled, Formie renders a type selector and uses a small front-end enhancement to update the value input’s native type and keyboard hints as the user switches between URL, Email, Phone and SMS.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>Custom Field is not automatic support for every Craft field class. A Craft field needs a Formie adapter so its value can be submitted, stored, displayed and exported consistently.</p><p>For adapter development, see <a href="/developers/custom-field#custom-field-adapters">Custom Field adapters</a>.</p>',17)])])}const m=t(o,[["render",r]]);export{h as __pageData,m as default};
